#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    unordered_map<string,int> a,b;
    for (int i=0;i<n;i++){
        string s; cin>>s;
        a[s]++;
    }
    for (int i=0;i<n;i++){
        string s; cin>>s;
        b[s]++;
    }
    long long ans = 0;
    // length 1 strings
    int aM = a["M"], aS = a["S"], aL = a["L"];
    int bM = b["M"], bS = b["S"], bL = b["L"];
    ans += (abs(aM-bM)+abs(aS-bS)+abs(aL-bL))/2;
    // pairs of length >1
    auto addPair = [&](const string& s1, const string& s2){
        ans += abs(a[s1] - b[s1]); // same as for s2
    };
    addPair("XS","XL");
    addPair("XXS","XXL");
    addPair("XXXS","XXXL");
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<pair<long long, long long>> ev;
    ev.reserve(2LL * n);
    for (int i = 0; i < n; ++i) {
        long long l, r;
        cin >> l >> r;
        ev.emplace_back(l, 1);
        ev.emplace_back(r + 1, -1);
    }
    sort(ev.begin(), ev.end(),
         [](const auto& a, const auto& b){ return a.first < b.first; });

    vector<unsigned long long> ans(n + 1, 0);
    long long cur = 0;
    long long prev = ev[0].first;
    size_t i = 0;
    while (i < ev.size()) {
        long long x = ev[i].first;
        unsigned long long len = static_cast<unsigned long long>(x - prev);
        if (cur > 0) ans[cur] += len;
        while (i < ev.size() && ev[i].first == x) {
            cur += ev[i].second;
            ++i;
        }
        prev = x;
    }

    for (int k = 1; k <= n; ++k) {
        if (k > 1) cout << ' ';
        cout << ans[k];
    }
    cout << '\n';
    return 0;
}

